/**
 * ============================================================
 *  TEMPORARY MOCK DATA - NOT REAL SIMULATION RESULTS
 * ============================================================
 * Used only when VITE_USE_MOCKS=true, so layout work can continue while
 * the backend is unavailable. The numbers below are generated by a tiny
 * toy model and have NO physical meaning. Delete this folder (and the
 * USE_MOCKS branches in src/services/api.ts) once the real API is connected.
 */
import type {
  CircuitCatalogueResponse,
  CircuitId,
  ComparisonNoiseMode,
  CountMap,
  DepthSweepRequest,
  DepthSweepResponse,
  HealthResponse,
  NoiseComparisonRequest,
  NoiseComparisonResponse,
  ProbabilityMap,
  SimulationNoiseMode,
  SimulationRequest,
  SimulationResponse,
} from '../types/api';

const delay = (ms = 350) => new Promise((r) => setTimeout(r, ms));

const CATALOGUE: CircuitCatalogueResponse = {
  circuits: [
    { id: 'bell', label: 'Bell', description: '[MOCK] Bell pair on qubits 0 and 1.', min_qubits: 2, max_qubits: 8, supports_custom_layers: false },
    { id: 'ghz', label: 'GHZ', description: '[MOCK] Multi-qubit GHZ state.', min_qubits: 2, max_qubits: 8, supports_custom_layers: false },
    { id: 'qft_like', label: 'QFT-like', description: '[MOCK] Compact interference circuit.', min_qubits: 1, max_qubits: 8, supports_custom_layers: false },
    { id: 'custom', label: 'Custom layered', description: '[MOCK] Parameterized layers.', min_qubits: 1, max_qubits: 8, supports_custom_layers: true, min_layers: 1, max_layers: 10 },
  ],
};

function allBitstrings(n: number): string[] {
  return Array.from({ length: 2 ** n }, (_, i) => i.toString(2).padStart(n, '0'));
}

function idealProbs(circuit: CircuitId, n: number, layers = 3): ProbabilityMap {
  const zeros = '0'.repeat(n);
  const ones = '1'.repeat(n);
  if (circuit === 'bell') {
    const pad = '1'.repeat(Math.max(0, n - 2));
    return { [pad + '00']: 0.5, [pad + '11']: 0.5 };
  }
  if (circuit === 'ghz') return { [zeros]: 0.5, [ones]: 0.5 };
  const all = allBitstrings(n);
  if (circuit === 'qft_like') return Object.fromEntries(all.map((b) => [b, 1 / all.length]));
  // custom: deterministic pseudo-random spread that depends on layers
  const w = all.map((_, i) => 1 + Math.abs(Math.sin((i + 1) * layers * 1.7)));
  const s = w.reduce((a, b) => a + b, 0);
  return Object.fromEntries(all.map((b, i) => [b, w[i] / s]));
}

const MODE_STRENGTH: Record<SimulationNoiseMode, number> = {
  ideal: 0, depolarizing: 0.06, bit_flip: 0.05, thermal: 0.08, readout: 0.03, combined: 0.12,
};

function noisy(ideal: ProbabilityMap, n: number, eps: number): ProbabilityMap {
  const all = allBitstrings(n);
  const out: ProbabilityMap = {};
  for (const b of all) out[b] = (1 - eps) * (ideal[b] ?? 0) + eps / all.length;
  return out;
}

function sample(p: ProbabilityMap, shots: number): { counts: CountMap; probs: ProbabilityMap } {
  const counts: CountMap = {};
  let total = 0;
  for (const [b, v] of Object.entries(p)) {
    const jitter = 1 + (Math.random() - 0.5) * 0.06;
    const c = Math.max(0, Math.round(v * shots * jitter));
    if (c > 0) { counts[b] = c; total += c; }
  }
  // make counts sum to shots
  const keys = Object.keys(counts).sort((a, b) => counts[b] - counts[a]);
  if (keys.length) counts[keys[0]] += shots - total;
  const probs = Object.fromEntries(Object.entries(counts).map(([b, c]) => [b, c / shots]));
  return { counts, probs };
}

function tvd(p: ProbabilityMap, q: ProbabilityMap): number {
  const keys = new Set([...Object.keys(p), ...Object.keys(q)]);
  let s = 0;
  keys.forEach((k) => { s += Math.abs((p[k] ?? 0) - (q[k] ?? 0)); });
  return 0.5 * s;
}

export const mockApi = {
  async getHealth(): Promise<HealthResponse> {
    await delay(150);
    return { status: 'ok', service: 'quantum-simulation-api (MOCK)', version: '1.0.0', simulator: 'qiskit_aer' };
  },
  async getCircuits(): Promise<CircuitCatalogueResponse> {
    await delay(150);
    return CATALOGUE;
  },
  async runSimulation(req: SimulationRequest): Promise<SimulationResponse> {
    await delay();
    const shots = req.shots ?? 2000;
    const mode = req.noise_mode ?? 'ideal';
    const layers = req.custom_layers ?? 3;
    const ideal = sample(idealProbs(req.circuit, req.n_qubits, layers), shots);
    const primary = mode === 'ideal' ? ideal : sample(noisy(idealProbs(req.circuit, req.n_qubits, layers), req.n_qubits, MODE_STRENGTH[mode]), shots);
    const withIdeal = req.include_ideal_reference !== false;
    return {
      run_id: 'mock-' + Math.random().toString(36).slice(2, 10),
      circuit: req.circuit, n_qubits: req.n_qubits, shots, noise_mode: mode,
      custom_layers: req.circuit === 'custom' ? layers : null,
      circuit_depth: 2 + (req.circuit === 'custom' ? layers * 2 : req.n_qubits),
      gate_count: 2 + (req.circuit === 'custom' ? layers * req.n_qubits * 2 : req.n_qubits),
      bitstring_order: 'q[n-1]_to_q[0]',
      counts: primary.counts, probabilities: primary.probs,
      ideal_counts: withIdeal ? ideal.counts : null,
      ideal_probabilities: withIdeal ? ideal.probs : null,
      metrics: { distribution_distance: withIdeal ? tvd(primary.probs, ideal.probs) : null, success_probability: null },
      metadata: { simulator: 'MOCK', metric_definition: 'total_variation_distance', status: 'completed' },
    };
  },
  async runNoiseComparison(req: NoiseComparisonRequest): Promise<NoiseComparisonResponse> {
    await delay();
    const shots = req.shots ?? 2000;
    const layers = req.custom_layers ?? 3;
    const base = idealProbs(req.circuit, req.n_qubits, layers);
    const ideal = sample(base, shots).probs;
    const modes: ComparisonNoiseMode[] = req.noise_modes ?? ['depolarizing', 'bit_flip', 'thermal', 'readout', 'combined'];
    return {
      circuit: req.circuit, n_qubits: req.n_qubits, shots, bitstring_order: 'q[n-1]_to_q[0]',
      ideal_probabilities: ideal,
      results: modes.map((m) => {
        const s = sample(noisy(base, req.n_qubits, MODE_STRENGTH[m]), shots);
        return { noise_mode: m, counts: s.counts, probabilities: s.probs, distribution_distance: tvd(s.probs, ideal) };
      }),
      metric_definition: 'total_variation_distance',
    };
  },
  async runDepthSweep(req: DepthSweepRequest): Promise<DepthSweepResponse> {
    await delay();
    const shots = req.shots ?? 2000;
    const depths = req.depths ?? [1, 2, 3, 4, 5, 6];
    const modes: ComparisonNoiseMode[] = req.noise_modes ?? ['combined'];
    const results = depths.flatMap((d) => modes.map((m) => {
      const base = idealProbs('custom', req.n_qubits, d);
      const ideal = sample(base, shots).probs;
      const nz = sample(noisy(base, req.n_qubits, Math.min(0.9, MODE_STRENGTH[m] * (1 + d * 0.35))), shots).probs;
      return { depth: d, noise_mode: m, ideal_probabilities: ideal, noisy_probabilities: nz, distribution_distance: tvd(nz, ideal) };
    }));
    return { n_qubits: req.n_qubits, shots, noise_modes: modes, metric_definition: 'total_variation_distance', results };
  },
};
